package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
)

type diffReport struct {
	ThreatCountDelta    int            `json:"threat_count_delta"`
	ThreatCountPctChange float64        `json:"threat_count_pct_change"`
	RiskDelta           float64        `json:"risk_delta"`
	RiskPctChange       float64        `json:"risk_pct_change"`
	RiskTrend           string         `json:"risk_trend"`
	NewActors           []string       `json:"new_actors"`
	GoneActors          []string       `json:"gone_actors"`
	PersistentActors    []string       `json:"persistent_actors"`
	ActorCountDeltas    map[string]int `json:"actor_count_deltas"`
	TypeShift           map[string]int `json:"type_shift"`
	CampaignDelta       int            `json:"campaign_delta"`
	RiskCategoryChange  diffCategory   `json:"risk_category_change"`
	Escalation          bool           `json:"escalation"`
}

type diffCategory struct {
	From string `json:"from"`
	To   string `json:"to"`
}

func runDiff(args []string) int {
	reader := bufio.NewReader(os.Stdin)

	var reports []aggregateReport
	for {
		line, err := reader.ReadString('\n')
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			if err != nil {
				break
			}
			continue
		}

		var report aggregateReport
		if jerr := json.Unmarshal([]byte(trimmed), &report); jerr != nil {
			fmt.Fprintln(os.Stderr, "error: malformed JSON input:", jerr)
			return 2
		}

		reports = append(reports, report)
		if len(reports) >= 2 {
			break
		}

		if err != nil {
			break
		}
	}

	if len(reports) < 2 {
		fmt.Fprintln(os.Stderr, "error: expected two aggregate JSON objects on stdin")
		return 1
	}

	baseline := reports[0]
	current := reports[1]

	report := diffReport{
		ThreatCountDelta: current.TotalThreats - baseline.TotalThreats,
		RiskDelta:        current.GlobalMeanRisk - baseline.GlobalMeanRisk,
		NewActors:        []string{},
		GoneActors:       []string{},
		PersistentActors: []string{},
		ActorCountDeltas: map[string]int{},
		TypeShift:        map[string]int{},
		CampaignDelta:    current.TotalCampaigns - baseline.TotalCampaigns,
		RiskCategoryChange: diffCategory{
			From: baseline.GlobalRiskCategory,
			To:   current.GlobalRiskCategory,
		},
		Escalation: riskCategoryRank(current.GlobalRiskCategory) > riskCategoryRank(baseline.GlobalRiskCategory),
	}

	report.ThreatCountPctChange = pctChange(report.ThreatCountDelta, baseline.TotalThreats)
	report.RiskPctChange = pctChangeFloat(report.RiskDelta, baseline.GlobalMeanRisk)

	switch {
	case report.RiskDelta > 0:
		report.RiskTrend = "increasing"
	case report.RiskDelta < 0:
		report.RiskTrend = "decreasing"
	default:
		report.RiskTrend = "stable"
	}

	actors := make(map[string]struct{}, len(baseline.CombinedActorCounts)+len(current.CombinedActorCounts))
	for actor := range baseline.CombinedActorCounts {
		actors[actor] = struct{}{}
	}
	for actor := range current.CombinedActorCounts {
		actors[actor] = struct{}{}
	}

	for actor := range actors {
		baseCount := baseline.CombinedActorCounts[actor]
		curCount := current.CombinedActorCounts[actor]
		report.ActorCountDeltas[actor] = curCount - baseCount

		_, inBase := baseline.CombinedActorCounts[actor]
		_, inCur := current.CombinedActorCounts[actor]
		if inBase && inCur {
			report.PersistentActors = append(report.PersistentActors, actor)
		} else if inCur {
			report.NewActors = append(report.NewActors, actor)
		} else {
			report.GoneActors = append(report.GoneActors, actor)
		}
	}
	sort.Strings(report.NewActors)
	sort.Strings(report.GoneActors)
	sort.Strings(report.PersistentActors)

	types := make(map[string]struct{}, len(baseline.TypeCounts)+len(current.TypeCounts))
	for t := range baseline.TypeCounts {
		types[t] = struct{}{}
	}
	for t := range current.TypeCounts {
		types[t] = struct{}{}
	}
	for t := range types {
		report.TypeShift[t] = current.TypeCounts[t] - baseline.TypeCounts[t]
	}

	out, err := json.Marshal(report)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error: encoding diff report:", err)
		return 1
	}
	fmt.Println(string(out))
	return 0
}

func pctChange(delta int, baseline int) float64 {
	if baseline == 0 {
		if delta > 0 {
			return 100.0
		}
		if delta < 0 {
			return -100.0
		}
		return 0.0
	}
	return round2(float64(delta) / float64(baseline) * 100.0)
}

func pctChangeFloat(delta float64, baseline float64) float64 {
	if baseline == 0 {
		if delta > 0 {
			return 100.0
		}
		if delta < 0 {
			return -100.0
		}
		return 0.0
	}
	return round2(delta / baseline * 100.0)
}

func riskCategoryRank(category string) int {
	switch category {
	case "low":
		return 1
	case "medium":
		return 2
	case "high":
		return 3
	case "critical":
		return 4
	default:
		return 0
	}
}
EOF
